SCORE_FIELDS = ("identity", "instruction", "quality")
SCORE_LABELS = {"identity": "정체성", "instruction": "포즈·구도 지시 준수", "quality": "품질"}
# What the recommendation maximises. Identity first: every later step assumes the picture is the same person.
WEIGHTS = {"identity": 0.45, "instruction": 0.30, "quality": 0.25}


def slots(limit=None):
    return SLOTS[:limit] if limit else list(SLOTS)


def prompt_for(card, slot):
    """`trigger, caption_base, fixed_traits, outfit, slot wording`, in that order (spec 3.4)."""
    parts = [card.get("trigger", ""), card.get("caption_base", "")]
    parts += list(card.get("fixed_traits") or [])
    default_outfit = (card.get("outfits") or {}).get("default", "")
    parts.append(default_outfit)
    parts.append(slot.get("prompt", ""))
    return ", ".join(p.strip() for p in parts if p and p.strip())


# --------------------------------------------------------------------------------------------- tool2 side (method A)
def tool2_dataset(folder):
    """{image name: caption} for the images tool2 already made for the character."""
    folder = Path(folder)
    out = {}
    if not folder.is_dir():
        return out
    for png in sorted(folder.glob("*.png")):
        caption = png.with_suffix(".txt")
        out[png.name] = caption.read_text(encoding="utf-8-sig").strip() if caption.is_file() else ""
    return out


def match_slot(slot, captions, used):
    """The tool2 image that best fits a slot, from its caption. Returns (name, caption) or (None, reason).

    `used` keeps one tool2 image from standing in for two slots. A slot with no unused candidate is reported missing
    instead of borrowing a picture that already illustrates another slot: the comparison reads a sheet where each
    tool2 column is the picture tool2 made *for that slot*, and a borrowed one would be scored twice under two names.

    An image tool2 made for the same category wins ties (an `expressions_*` file for an expression slot): without
    that, "upper body, front view" alone matches a classroom background as well as a portrait.
    """
    best, best_score = None, 0
    for name, caption in captions.items():
        if name in used:
            continue
        lowered = caption.lower()
        if not all(any(alt.lower() in lowered for alt in group) for group in slot["match"]):
            continue
        hits = sum(1 for group in slot["match"] for alt in group if alt.lower() in lowered)
        score = hits + (2 if name.startswith(slot["category"] + "_") else 0)
        if score > best_score:
            best, best_score = name, score
    if best is None:
        return None, "no tool2 image carries this slot's tags"
    return best, captions[best]


# --------------------------------------------------------------------------------------------- the manifest
def plan(exp_dir, card, *, epochs=(), seeds=(1003, 1004), slot_limit=None, tool2_folder=None,
         variants=("a", "b"), width=1024, height=1536, character_lora=None):
    """Build (and write) the work list. Returns the manifest, which `run()` then executes."""
    exp_dir = Path(exp_dir)
    chosen = slots(slot_limit)
    if not character_lora:
        name = (card.get("seed_lora") or {}).get("name")
        # "suamom_v1@28,62": the run and the epochs this comparison is allowed to use as snapshots.
        character_lora = (name + ("@" + ",".join(str(int(e)) for e in epochs) if epochs else "")) if name else None
    captions = tool2_dataset(tool2_folder) if tool2_folder else {}
    methods = ["qwen_edit"] + [f"krea2_{v}_e{int(e):03d}" for v in variants for e in epochs]
    tasks, used = [], set()
    for slot in chosen:
        name, _caption = match_slot(slot, captions, used)
        if name:
            used.add(name)
        for seed in seeds:
            base = {"slot_id": slot["id"], "category": slot["category"], "seed": int(seed)}
            tasks.append({
                **base, "method": "qwen_edit", "kind": "tool2",
                "file": f"images/qwen_edit/{slot['id']}__s{seed}.png",
                "source": str(Path(tool2_folder) / name) if name else None,
                "source_ref": name, "prompt": prompt_for(card, slot),
                "status": "pending" if name else "missing",
                "note": "" if name else "no matching tool2 image; generate it with the tool2 CLI or accept the gap",
            })
            for variant in variants:
                for epoch in epochs:
                    method = f"krea2_{variant}_e{int(epoch):03d}"
                    tasks.append({
                        **base, "method": method, "kind": "comfy", "variant": variant, "epoch": int(epoch),
                        "file": f"images/{method}/{slot['id']}__s{seed}.png",
                        "prompt": prompt_for(card, slot), "status": "pending", "note": "",
                    })
    missing = sorted({t["slot_id"] for t in tasks if t["status"] == "missing"})
    # A file already sitting where an unfillable slot would put one is left over from an older plan; it is named here
    # so it can be cleaned up, and `run()` never counts it as this slot's result.
    for task in tasks:
        if task["status"] == "missing" and (exp_dir / task["file"]).is_file():
            task["stale_file"] = True
    variant_notes = {}
    if "c" in variants:
        variant_notes["c"] = ("reference conditioning is wired (TextEncodeQwenImageEditPlus + "
                              "FluxKontextMultiReferenceLatentMethod) but the run needs reference images chosen per "
                              "slot and the krea2_style_reference LoRA is not installed; see PROGRESS.ko.md section 14")
    manifest = {
        "kind": "m0_comparison",
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "character": card,
        "character_lora": character_lora,
        "variants": list(variants),
        "epochs": [int(e) for e in epochs],
        "seeds": [int(s) for s in seeds],
        "size": {"width": int(width), "height": int(height)},
        "slots": chosen,
        "methods": methods,
        "tasks": tasks,
        "lineage_caps": lineage.caps(card.get("lineage")),
        "slots_without_tool2": missing,
        "variant_notes": variant_notes,
        "status": "planned",
    }
    write_manifest(exp_dir, manifest)
    return manifest


def manifest_path(exp_dir):
    return Path(exp_dir) / "experiment.json"


def read_manifest(exp_dir):
    return json.loads(manifest_path(exp_dir).read_text(encoding="utf-8"))


def write_manifest(exp_dir, manifest):
    path = manifest_path(exp_dir)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + ".tmp-" + os.urandom(4).hex())
    temp.write_text(json.dumps(manifest, ensure_ascii=False, indent=1), encoding="utf-8")
    os.replace(temp, path)


def pending(manifest):
    return [t for t in manifest["tasks"] if t["status"] in ("pending", "failed")]


def ensure_character_lora(method, epoch, lora_dir):
    """The character LoRA file for an epoch: the exact checkpoint, or the nearest epoch the run saved."""
    lora_dir = Path(lora_dir)
    files = sorted(lora_dir.glob("*.safetensors"))
    if not files:
        raise FileNotFoundError(f"no LoRA checkpoints under {lora_dir}")
    exact = [f for f in files if f.stem.endswith(f"-{int(epoch):06d}")]
    if exact:
        return exact[0]
    numbered = []
    for f in files:
        tail = f.stem.rsplit("-", 1)[-1]
        if tail.isdigit():
            numbered.append((int(tail), f))
    if not numbered:
        raise FileNotFoundError(f"no epoch-numbered LoRA under {lora_dir}")
    return min(numbered, key=lambda pair: abs(pair[0] - int(epoch)))[1]


def resolve_krea2_names(client, resolved):
    return {
        "a_unet": client.name_for("unet", resolved["krea2_turbo_dit"]),
        "b_unet": client.name_for("unet", resolved["krea2_raw_dit"]),
        "speed_lora": client.name_for("lora", resolved["krea2_turbo_lora"]),
        "clip": client.name_for("clip", resolved["krea2_text_encoder"]),
        "vae": client.name_for("vae", resolved["krea2_vae"]),
    }


def run(exp_dir, manifest, *, client, names, lora_dir, log=print, cancel=None):
    """Execute the pending tasks. Returns (done, skipped, failed, missing).

    A task whose file is already on disk is skipped, so rerunning the same command adds nothing: that is the M0
    acceptance criterion, and it is what makes a multi-hour comparison resumable.
    """
    exp_dir = Path(exp_dir)
    unsupported = [t["variant"] for t in manifest["tasks"] if t.get("variant") == "c"]
    if unsupported:
        raise ValueError("variant 'c' cannot be run by this harness yet: "
                         + manifest.get("variant_notes", {}).get("c", "no reference images are wired"))
    timings = read_timings(exp_dir)
    done = skipped = failed = missing = 0
    for task in manifest["tasks"]:
        out = exp_dir / task["file"]
        if task["status"] == "missing":
            # A slot the plan could not fill stays unfilled even if an older plan left a file at this path: recording
            # that file would put a picture into the comparison for a slot whose method never made one.
            missing += 1
            continue
        if out.is_file():
            if task["status"] != "done":
                task["status"] = "done"
            skipped += 1
            continue
        if cancel is not None and cancel():
            log("cancelled")
            break
        started = time.time()
        try:
            if task["kind"] == "tool2":
                source = Path(task["source"]) if task.get("source") else None
                if not source or not source.is_file():
                    task["status"] = "missing"
                    missing += 1
                    continue
                out.parent.mkdir(parents=True, exist_ok=True)
                temp = out.with_name(out.name + ".tmp")
                shutil.copy2(source, temp)
                os.replace(temp, out)
                task["status"] = "done"
                done += 1
                log(f"  {task['slot_id']} {task['method']}: copied {source.name}")
            else:
                lora = ensure_character_lora(task["method"], task["epoch"], lora_dir)
                graph = krea2_gen.build(
                    task["variant"],
                    unet=names["a_unet" if task["variant"] == "a" else "b_unet"],
                    clip=names["clip"], vae=names["vae"], prompt=task["prompt"],
                    width=manifest["size"]["width"], height=manifest["size"]["height"], seed=task["seed"],
                    character_lora=client.name_for("lora", str(lora)),
                    speed_lora=names["speed_lora"] if task["variant"] == "b" else None,
                    filename_prefix=f"pipeline_experiment/{task['slot_id']}",
                )
                out.parent.mkdir(parents=True, exist_ok=True)
                client.run(graph, out, slot_id=task["slot_id"], method=task["method"], seed=task["seed"])
                task["status"] = "done"
                done += 1
                log(f"  {task['slot_id']} {task['method']}: generated in {time.time() - started:.0f}s")
        except Exception as exc:  # noqa: BLE001 - one failed image must not end a multi-hour run
            task["status"] = "failed"
            task["error"] = f"{type(exc).__name__}: {exc}"
            failed += 1
            log(f"  {task['slot_id']} {task['method']}: FAILED {task['error'][:200]}")
        finally:
            task["seconds"] = round(time.time() - started, 1)
            timings[task_key(task)] = task["seconds"]
            write_timings(exp_dir, timings)
            write_manifest(exp_dir, manifest)
    manifest["status"] = "ran"
    write_manifest(exp_dir, manifest)
    write_candidates(exp_dir, manifest, lora_dir)
    log(f"done {done}, skipped {skipped} already present, failed {failed}, missing {missing}")
    return done, skipped, failed, missing


def task_key(task):
    return f"{task['slot_id']}__{task['method']}__s{task['seed']}"


def timings_path(exp_dir):
    return Path(exp_dir) / "timings.json"


def read_timings(exp_dir):
    try:
        return json.loads(timings_path(exp_dir).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def write_timings(exp_dir, timings):
    path = timings_path(exp_dir)
    temp = path.with_name(path.name + ".tmp")
    temp.write_text(json.dumps(timings, ensure_ascii=False, indent=1), encoding="utf-8")
    os.replace(temp, path)


def tool2_manifest(folder):
    """{file name: merged record} from the dataset folder's manifest.jsonl.

    tool2 appends a line each time it touches an image: the generation record (with `refs` and `prompt`), then caption
    rewrites. The later lines carry only `update` and `caption`, so records are merged instead of overwritten, or the
    provenance of every regenerated caption would be lost.
    """
    path = Path(folder) / "manifest.jsonl"
    out = {}
    if not path.is_file():
        return out
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except ValueError:
            continue
        name = record.get("file")
        if not name:
            continue
        merged = out.setdefault(name, {"file": name})
        merged.update({k: v for k, v in record.items() if v not in (None, "", [], {}) or k not in merged})
    return out


def tool2_parents(dataset_folder, characters_folder, image_name, log=print):
    """Source ids of the originals a tool2 image was edited from, read from tool2's own manifest.

    Returns (ids, reason). A tool2 image is an edit of originals in `characters/<name>/`, either copied whole
    (`source`) or edited with reference images (`refs`); the ids are over the original bytes, so they join the same
    lineage an original gets when a project records it.
    """
    if not dataset_folder or not characters_folder:
        return [], "no tool2 dataset or characters folder configured"
    record = tool2_manifest(dataset_folder).get(image_name)
    if not record:
        return [], "tool2 left no manifest record for this image"
    names = list(record.get("refs") or []) or ([record["source"]] if record.get("source") else [])
    ids = []
    for name in names:
        original = Path(characters_folder) / name
        try:
            ids.append(lineage.source_id(lineage.sha256_file(original)))
        except OSError:
            log(f"  parent not found: {original}")
    if not ids:
        return [], "none of the recorded parents exist under the characters folder"
    return ids, ""


def write_candidates(exp_dir, manifest, lora_dir):
    """Record lineage for every finished image, so an experiment image can be traced like any other candidate."""
    records = []
    caps = manifest.get("lineage_caps", {})
    tool2_cfg = manifest["character"].get("tool2") or {}
    for task in manifest["tasks"]:
        out = Path(exp_dir) / task["file"]
        if not out.is_file():
            continue
        slot = {"category": task["category"], "prompt": task["prompt"]}
        if task["kind"] == "tool2":
            parents, reason = tool2_parents(tool2_cfg.get("dataset"), tool2_cfg.get("characters"),
                                            task.get("source_ref") or "")
            extra = {} if parents else {"allow_missing_parents": True, "orphan_reason": reason}
            record = lineage.record(
                out, generator="qwen_edit", parent_ids=parents, train_generation=1, edit_depth=1, slot=slot,
                prompt=task["prompt"], seed=task["seed"], graph_version="tool2_qwen_edit",
                method=task["method"], tool2_source=task.get("source_ref"), **extra)
        else:
            lora = ensure_character_lora(task["method"], task["epoch"], lora_dir)
            # The snapshot a Krea2 image came from is the character LoRA at that epoch; when the card does not name the
            # run, say so explicitly rather than leaving the trace dangling.
            snapshot = manifest.get("character_lora") or \
                f"{manifest['character'].get('id', 'character')}@e{int(task['epoch']):03d}"
            record = lineage.record(
                out, generator="krea2_lora", parent_ids=[], train_generation=1, edit_depth=0, slot=slot,
                models={"dit": {"name": "krea2_turbo" if task["variant"] == "a" else "krea2_raw"},
                        "loras": [lineage.model_entry(lora, trained_on_snapshot=snapshot,
                                                     trained_on_generation=0)]},
                prompt=task["prompt"], seed=task["seed"], steps=krea2_gen.SAMPLING["steps"],
                cfg=krea2_gen.SAMPLING["cfg"], width=manifest["size"]["width"],
                height=manifest["size"]["height"], graph_version=krea2_gen.GRAPH_VERSION[task["variant"]],
                method=task["method"])
        try:
            lineage.check_generation(record, limit=int(caps.get("max_train_generation", 2)))
            lineage.check_edit_depth(record, limit=int(caps.get("max_edit_depth", 1)))
        except lineage.LineageError as exc:
            record["lineage_warning"] = str(exc)
        records.append(record)
    lineage.write_jsonl(Path(exp_dir) / "candidates.jsonl", records)
    return len(records)


# --------------------------------------------------------------------------------------------- the contact sheet
def write_sheet(exp_dir, manifest):
    """Write sheet.html and return its path. Cells are slot rows x method columns, inputs under each image."""
    exp_dir = Path(exp_dir)
    methods = manifest["methods"]
    by_key = {(t["slot_id"], t["method"], t["seed"]): t for t in manifest["tasks"]}
    timings = read_timings(exp_dir)
    seeds = manifest.get("seeds") or [0]
    rows = []
    for slot in manifest["slots"]:
        cells = []
        for method in methods:
            inner = []
            for seed in seeds:
                task = by_key.get((slot["id"], method, seed))
                if task is None:
                    inner.append('<div class="cell empty">-</div>')
                    continue
                rel = Path(task["file"]).as_posix()
                key = task_key(task)
                seconds = task.get("seconds") or timings.get(key)
                badge = f'<div class="meta">{html_escape(method)} · s{seed}' + (
                    f' · {seconds:.0f}s' if seconds else "") + "</div>"
                if not (exp_dir / task["file"]).is_file():
                    inner.append(f'<div class="cell missing">{badge}<div class="ph">'
                                 f'{html_escape(task["status"])}</div></div>')
                    continue
                inner.append(
                    f'<div class="cell">{badge}'
                    f'<a href="{rel}" target="_blank"><img loading="lazy" src="{rel}" alt="{html_escape(key)}"></a>'
                    f'<div class="score" data-task="{html_escape(key)}" data-slot="{html_escape(slot["id"])}" '
                    f'data-method="{html_escape(method)}" data-seed="{seed}">'
                    + "".join(f'<label>{SCORE_LABELS[f]} <input type="number" min="1" max="5" step="1" '
                              f'name="{f}"></label>' for f in SCORE_FIELDS)
                    + '<label class="note">메모 <input type="text" name="note"></label>'
                    + '<label class="err"><input type="checkbox" name="error"> 다른 캐릭터/심한 오류</label>'
                    + "</div></div>")
            cells.append(f'<td data-method="{html_escape(method)}">{"".join(inner)}</td>')
        rows.append(f'<tr><th>{html_escape(slot["id"])}<div class="meta">{html_escape(slot["category"])}</div>'
                    f'<div class="prompt">{html_escape(slot["prompt"])}</div></th>{"".join(cells)}</tr>')
    page = _PAGE_TEMPLATE.format(
        title=html_escape(f"M0 comparison — {manifest['character'].get('id', '')}"),
        head="".join(f"<th>{html_escape(m)}</th>" for m in methods),
        rows="".join(rows),
        summary=html_escape(_summary_line(manifest)),
    )
    path = exp_dir / "sheet.html"
    path.write_text(page, encoding="utf-8")
    return path


def html_escape(value):
    from html import escape
    return escape(str(value), quote=True)


def _summary_line(manifest):
    counts = {}
    for task in manifest["tasks"]:
        counts[task["status"]] = counts.get(task["status"], 0) + 1
    per_method = {}
    for task in manifest["tasks"]:
        if task.get("seconds"):
            per_method.setdefault(task["method"], []).append(task["seconds"])
    timing = "; ".join(f"{m} 평균 {statistics.mean(v):.0f}s ({len(v)}장)" for m, v in sorted(per_method.items()))
    return (f"{len(manifest['tasks'])} tasks · " + ", ".join(f"{k} {v}" for k, v in sorted(counts.items()))
            + ((" · " + timing) if timing else ""))


