def scores_csv(exp_dir):
    return Path(exp_dir) / "scores.csv"


def write_scores(exp_dir, rows):
    """Write the score rows as CSV (fields in a fixed order). Returns the path."""
    path = scores_csv(exp_dir)
    columns = ["slot", "method", "seed", "task", *SCORE_FIELDS, "error", "note"]
    temp = path.with_name(path.name + ".tmp")
    with open(temp, "w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=columns, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow(row)
    os.replace(temp, path)
    return path


def read_scores(exp_dir):
    path = scores_csv(exp_dir)
    if not path.is_file():
        return []
    with open(path, encoding="utf-8-sig", newline="") as handle:
        return [row for row in csv.DictReader(handle)]


def make_server(exp_dir, port=8765, log=print):
    """A stdlib HTTP server for one experiment folder: the sheet, its images, and the score endpoint.

    Returned unstarted so a caller (the tests) can shut it down cleanly; `serve()` starts it and blocks.
    """
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

    root = Path(exp_dir).resolve()

    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *_args):
            pass

        def _send(self, code, body, ctype="text/plain; charset=utf-8"):
            data = body if isinstance(body, bytes) else body.encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def do_GET(self):
            rel = self.path.split("?", 1)[0].lstrip("/") or "sheet.html"
            target = (root / rel).resolve()
            if not target.is_relative_to(root) or not target.is_file():
                return self._send(404, "not found")
            ctype = {".html": "text/html; charset=utf-8", ".png": "image/png", ".jpg": "image/jpeg",
                     ".webp": "image/webp", ".csv": "text/csv; charset=utf-8",
                     ".json": "application/json; charset=utf-8"}.get(target.suffix.lower(),
                                                                    "application/octet-stream")
            self._send(200, target.read_bytes(), ctype)

        def do_POST(self):
            if self.path != "/scores":
                return self._send(404, "not found")
            length = int(self.headers.get("Content-Length") or 0)
            try:
                payload = json.loads(self.rfile.read(length) or b"{}")
            except ValueError:
                return self._send(400, "bad json")
            rows = payload.get("rows") or []
            path = write_scores(root, rows)
            log(f"scores saved: {path} ({len(rows)} rows)")
            self._send(200, json.dumps({"saved": len(rows), "path": str(path)}))

    return ThreadingHTTPServer(("127.0.0.1", port), Handler)


def serve(exp_dir, port=8765, log=print):
    """Serve the sheet from a stdlib HTTP server so the save button can write scores.csv in place."""
    server = make_server(exp_dir, port, log)
    log(f"serving {Path(exp_dir).resolve()} at http://127.0.0.1:{server.server_address[1]}/sheet.html")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return server


# --------------------------------------------------------------------------------------------- the report
def score_rows(rows):
    """Keep only rows that carry at least one numeric mark, converted to floats."""
    out = []
    for row in rows:
        mark = {}
        for field in SCORE_FIELDS:
            raw = str(row.get(field, "")).strip()
            if raw:
                try:
                    mark[field] = float(raw)
                except ValueError:
                    pass
        if mark:
            out.append({**row, "_scores": mark, "error": str(row.get("error", "")).strip().lower() in ("1", "true")})
    return out


def weighted(scores):
    total = sum(WEIGHTS[f] for f in scores)
    return sum(WEIGHTS[f] * value for f, value in scores.items()) / total if total else 0.0


def aggregate(rows):
    """Per-method means and weighted score, plus a per-category breakdown (side and back angles matter)."""
    graded = score_rows(rows)
    buckets = {}
    for row in graded:
        method = row.get("method", "?")
        bucket = buckets.setdefault(method, {"n": 0, "errors": 0, "scores": {f: [] for f in SCORE_FIELDS},
                                             "categories": {}, "weighted": []})
        bucket["n"] += 1
        bucket["errors"] += 1 if row["error"] else 0
        for field, value in row["_scores"].items():
            bucket["scores"][field].append(value)
        score = weighted(row["_scores"])
        bucket["weighted"].append(score)
        category = (row.get("slot") or "?").split("_")[0]
        cat = bucket["categories"].setdefault(category, {"n": 0, "weighted": []})
        cat["n"] += 1
        cat["weighted"].append(score)
    summary = {}
    for method, bucket in buckets.items():
        summary[method] = {
            "n": bucket["n"],
            "errors": bucket["errors"],
            "error_rate": bucket["errors"] / bucket["n"] if bucket["n"] else 0.0,
            "means": {f: (statistics.mean(v) if v else None) for f, v in bucket["scores"].items()},
            "weighted": statistics.mean(bucket["weighted"]) if bucket["weighted"] else None,
            "categories": {c: {"n": v["n"], "weighted": statistics.mean(v["weighted"]) if v["weighted"] else None}
                           for c, v in bucket["categories"].items()},
        }
    return summary


def recommendation(summary):
    """One method, with the numbers that decided it. Ties break on the error rate, then on the method name."""
    scored = [(m, s) for m, s in summary.items() if s.get("weighted") is not None]
    if not scored:
        return None, ["아직 점수가 없습니다. 시트에서 1~5점을 입력하고 저장하세요."]
    order = sorted(scored, key=lambda pair: (-pair[1]["weighted"], pair[1]["error_rate"], pair[0]))
    name, best = order[0]
    means = best["means"]
    reasons = [f"{name}의 가중 점수 {best['weighted']:.2f} "
               f"(정체성 {_fmt(means.get('identity'))}, 지시 준수 {_fmt(means.get('instruction'))}, "
               f"품질 {_fmt(means.get('quality'))})",
               f"오류율 {best['error_rate']:.0%} ({best['errors']}/{best['n']})"]
    if len(order) > 1:
        second_name, second = order[1]
        gap = best["weighted"] - second["weighted"]
        reasons.append(f"2위 {second_name}와의 차이 {gap:.2f}")
        if gap < 0.2:
            reasons.append("차이가 0.2 미만이라 표본을 늘리기 전에는 확정으로 보기 어렵습니다")
    angles = (best["categories"].get("ang") or {}).get("weighted")
    if angles is not None:
        reasons.append(f"각도 슬롯(측면·후면 포함)만의 가중 점수 {angles:.2f}; "
                       f"{'측면·후면이 평균을 끌어내리지 않았습니다' if angles >= best['weighted'] else '측면·후면에서 약합니다'}")
    return name, reasons


def _fmt(value):
    return "-" if value is None else f"{value:.2f}"


def write_report(exp_dir, manifest, log=print):
    """Turn scores.csv into report.md (aggregate table + recommendation). Returns (path, method, reasons)."""
    exp_dir = Path(exp_dir)
    rows = read_scores(exp_dir)
    summary = aggregate(rows)
    best, reasons = recommendation(summary)
    lines = [f"# M0 비교 리포트 — {manifest['character'].get('id', '')}", "",
             f"- 슬롯 {len(manifest['slots'])} × 시드 {len(manifest.get('seeds') or [])}"
             f" × 방식 {len(manifest['methods'])}",
             f"- 점수 {len(score_rows(rows))}건",
             f"- LoRA {manifest.get('character_lora') or '(none)'}"]
    for variant, note in (manifest.get("variant_notes") or {}).items():
        lines.append(f"- 구성 ({variant}) 제외: {note}")
    if manifest.get("slots_without_tool2"):
        lines.append(f"- 툴2 이미지가 없어 비어 있는 슬롯: {', '.join(manifest['slots_without_tool2'])}")
    lines.append("")
    if summary:
        lines += ["| 방식 | n | 정체성 | 지시 준수 | 품질 | 가중 | 오류율 |", "|---|---|---|---|---|---|---|"]
        for method, s in sorted(summary.items(), key=lambda kv: -(kv[1]["weighted"] or 0)):
            m = s["means"]
            lines.append(f"| {method} | {s['n']} | {_fmt(m.get('identity'))} | {_fmt(m.get('instruction'))} | "
                         f"{_fmt(m.get('quality'))} | {_fmt(s['weighted'])} | {s['error_rate']:.0%} |")
        lines.append("")
    lines.append("## 추천")
    lines += [f"**{best}**", ""] + [f"- {r}" for r in reasons] if best else reasons
    lines.append("")
    path = exp_dir / "report.md"
    path.write_text("\n".join(lines), encoding="utf-8")
    log(f"report: {path}")
    return path, best, reasons


# --------------------------------------------------------------------------------------------- command line
def _list(value, cast=str):
    if value is None:
        return None
    return [cast(part.strip()) for part in str(value).split(",") if part.strip()]


def cmd_plan(args):
    card = json.loads(Path(args.card).read_text(encoding="utf-8-sig"))
    seed_lora = card.get("seed_lora") or {}
    epochs = _list(args.epochs, int) or [int(e) for e in (seed_lora.get("epochs") or [])]
    variants = tuple(_list(args.variants) or ("a", "b"))
    seeds = _list(args.seeds, int) or (1003, 1004)
    tool2_folder = args.tool2_dataset or (card.get("tool2") or {}).get("dataset")
    manifest = plan(
        args.out, card, epochs=epochs, seeds=seeds, slot_limit=args.slots, tool2_folder=tool2_folder,
        variants=variants, width=args.width, height=args.height,
        character_lora=(seed_lora.get("name") or "") + ("@" + ",".join(str(e) for e in epochs) if epochs else ""))
    counts = {}
    for task in manifest["tasks"]:
        counts[task["status"]] = counts.get(task["status"], 0) + 1
    print(f"planned {len(manifest['tasks'])} tasks: " + ", ".join(f"{k} {v}" for k, v in sorted(counts.items())))
    print("manifest:", manifest_path(args.out))
    if manifest["slots_without_tool2"]:
        print(f"{len(manifest['slots_without_tool2'])} slot(s) have no tool2 image yet: "
              + ", ".join(manifest["slots_without_tool2"]))
    return 0


def cmd_run(args):
    manifest = read_manifest(args.out)
    settings = models.comfy_settings()
    client = comfy_mod.Comfy(settings["url"], comfy_root=settings["root"],
                             timeout=int(settings.get("request_timeout") or 1800),
                             journal=(AUTO / "state" / "prompt_journal"))
    if not client.ping():
        print(f"ComfyUI is not answering at {client.url}", file=sys.stderr)
        return 1
    problems = models.problems("krea2", require_optional=("krea2_turbo_lora",))
    if problems:
        print("model problems: " + "; ".join(problems), file=sys.stderr)
        return 1
    names = resolve_krea2_names(client, models.resolve("krea2"))
    seed_lora = manifest["character"].get("seed_lora") or {}
    lora_dir = Path(args.lora_dir or seed_lora.get("dir") or "")
    if not lora_dir.is_dir():
        print(f"the character LoRA folder does not exist: {lora_dir}", file=sys.stderr)
        return 1
    done, skipped, failed, missing = run(args.out, manifest, client=client, names=names, lora_dir=lora_dir)
    print(f"generated {done}, skipped {skipped}, failed {failed}, missing {missing}")
    return 1 if failed else 0


def cmd_sheet(args):
    path = write_sheet(args.out, read_manifest(args.out))
    print("sheet:", path)
    if args.serve:
        webbrowser.open(f"http://127.0.0.1:{args.port}/sheet.html")
        serve(args.out, port=args.port)
    else:
        webbrowser.open(Path(path).resolve().as_uri())
    return 0


def cmd_report(args):
    path, _best, _reasons = write_report(args.out, read_manifest(args.out))
    print(path.read_text(encoding="utf-8"))
    return 0


def cmd_status(args):
    manifest = read_manifest(args.out)
    counts = {}
    for task in manifest["tasks"]:
        counts[task["status"]] = counts.get(task["status"], 0) + 1
    print(json.dumps({"tasks": len(manifest["tasks"]), "status": counts, "methods": manifest["methods"],
                      "seeds": manifest.get("seeds"), "slots_without_tool2": manifest["slots_without_tool2"]},
                     ensure_ascii=False, indent=1))
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(description="M0 comparison harness",
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("command", choices=["plan", "run", "sheet", "report", "status"])
    parser.add_argument("--out", default=str(AUTO / "experiments" / "m0_suamom"))
    parser.add_argument("--card", default=str(AUTO / "experiments" / "suamom_card.json"))
    parser.add_argument("--epochs", help="comma list of LoRA epochs to compare")
    parser.add_argument("--variants", help="comma list of Krea2 configurations: " + ",".join(krea2_gen.VARIANTS))
    parser.add_argument("--seeds", help="comma list of seeds (default 1003,1004)")
    parser.add_argument("--slots", type=int, help="use only the first N slots (a pilot run)")
    parser.add_argument("--width", type=int, default=1024)
    parser.add_argument("--height", type=int, default=1536)
    parser.add_argument("--tool2-dataset", help="tool2's dataset folder for this character (method A)")
    parser.add_argument("--lora-dir", help="folder of the character LoRA's epoch checkpoints")
    parser.add_argument("--serve", action="store_true", help="serve the sheet so scores save in place")
    parser.add_argument("--port", type=int, default=8765)
    args = parser.parse_args(argv)
    return {"plan": cmd_plan, "run": cmd_run, "sheet": cmd_sheet, "report": cmd_report,
            "status": cmd_status}[args.command](args)


if __name__ == "__main__":
    if str(ROOT / "src") not in sys.path:
        sys.path.insert(0, str(ROOT / "src"))
    raise SystemExit(main())
